 [STAThread]static int Main(string[] args){SetProcessDpiAwarenessContext(new IntPtr(-4));Application.EnableVisualStyles();if(args.Length==2&&args[0]=="--dock-helper")return ClickHelper(args[1]);if(args.Length==2&&args[0]=="--source"){Application.Run(new EffectSource(args[1]));return 0;}root=args[0];output=args[1];previewOnly=Array.IndexOf(args,"--preview-only")>=0;interactionOnly=Array.IndexOf(args,"--stage-interaction-only")>=0;stageLayoutOnly=Array.IndexOf(args,"--stage-layout-only")>=0;int result=0;Directory.CreateDirectory(root);Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"checks.txt"),"");owner=new Form{Text="PrismGlass · isolated native acceptance",StartPosition=FormStartPosition.Manual,Bounds=new Rectangle(60,60,1100,900),BackColor=Color.FromArgb(17,25,43),ShowInTaskbar=false,TopMost=true};owner.Shown+=async(s,e)=>{try{await Run();}catch(Exception ex){result=1;File.AppendAllText(Path.Combine(output,"checks.txt"),ex+Environment.NewLine);}finally{if(eventHook!=IntPtr.Zero)UnhookWinEvent(eventHook);foreach(var p in processes){try{if(!p.HasExited)p.Kill();p.Dispose();}catch{}}owner.Close();}};Application.Run(owner);return result;}
